// S2 em JS (s2.js / nodejs-s2)
import { CellId, LatLng } from 's2geometry';

const point = LatLng.fromDegrees(-23.5505, -46.6333);
const cell  = CellId.fromLatLng(point);
const lvl15 = cell.parentL(15);  // level 15 = ~250m² no equador
console.log(lvl15.toToken());     // ex: "94ce3ff4" (string hex compacta)

